/// <summary>
/// The service class for Purchase order cancel process.
/// </summary>
class METPurchaseOrderLineService extends SysOperationServiceBase
{
    #OCCRetryCount
    
}

Method.Source:
    /// <summary>
    /// cancels the Purchase order.
    /// </summary>
    /// <param name="purchaseOrderLineIntegrationStatusRequest">
    /// The contract instance
    /// </param>
    /// <returns>
    /// The response <c>METPurchaseOrderResponseContract</c>
    /// </returns>
    [AifCollectionType('purchaseOrderLineIntegrationStatusRequest', Types::Class, classStr(METPurchaseOrderLineIntegrationStatusRequestContract))]
    public METPurchaseOrderLineResponseContract updateIntegrationStatus(List purchaseOrderLineIntegrationStatusRequest)
    {
        METProcessingStatus result;
        Description255      message = "@MET:NoRecordsUpdated"; //default message

        [result, message] = this.processUpdateIntegrationStatus(purchaseOrderLineIntegrationStatusRequest);
        
        return METPurchaseOrderLineResponseContract::newFromParameters(result, message);
    }

    /// <summary>
    /// Process the Purchase order lines
    /// </summary>
    /// <param name="_purchaseOrderLineIntegrationStatusRequest">List of contracts</param>
    /// <returns>Container of Results</returns>
    public container processUpdateIntegrationStatus(List _purchaseOrderLineIntegrationStatusRequest)
    {
        ListEnumerator purchaseOrderLineListEnumerator = _purchaseOrderLineIntegrationStatusRequest.getEnumerator();

        METProcessingStatus processingStatus;
        Description255      processingMessage;

        PurchId             purchId;
        TradeLineNumber     lineNum;
        DataAreaId          dataAreaId;
        METIntegrationStatus integrationStatus;
        Set                 purchIdSet;

        PurchTable          purchTable;
        PurchLine           purchLine;
        METPurchTable       metPurchTable;
        METPurchLine        metPurchLine;

        METPurchaseOrderLineIntegrationStatusRequestContract purchaseOrderLineIntegrationStatusRequestContract;
        
        try
        {
            purchIdSet = new Set(Types::String);

            while(purchaseOrderLineListEnumerator.moveNext())
            {
                purchaseOrderLineIntegrationStatusRequestContract = purchaseOrderLineListEnumerator.current() as METPurchaseOrderLineIntegrationStatusRequestContract;

                PurchId             = purchaseOrderLineIntegrationStatusRequestContract.parmPurchId();
                lineNum             = purchaseOrderLineIntegrationStatusRequestContract.parmLineNum();
                dataAreaId          = purchaseOrderLineIntegrationStatusRequestContract.parmDataAreaId();
                integrationStatus   = purchaseOrderLineIntegrationStatusRequestContract.getIntegrationStatus();

                changecompany(dataAreaId)
                {
                    if(!purchIdSet.in(purchId))
                    {
                        purchIdSet.add(purchId);

                        purchTable = purchTable::find(purchId);
                        
                        if(purchTable)
                        {
                            metPurchTable = purchTable.metPurchTable();

                            //Extended table design pattern was introduced late. Some extension records may not exist
                            if(!metPurchTable)
                            {
                                metPurchTable = purchTable.metCreateMETPurchTable();
                            }

                            metPurchTable.updateIntegrationStatus(integrationStatus);

                            processingStatus = METProcessingStatus::Success;
                            processingMessage = "@MET:PurchaseOrderUpdateSuccessful";
                        }
                        else
                        {
                            processingStatus = METProcessingStatus::Error;
                            processingMessage = "@MET:PurchaseOrderNotFound";
                        }
                    }

                    if(processingStatus == METProcessingStatus::Success)
                    {
                        purchLine = purchLine::find(purchId, lineNum);

                        if(purchLine)
                        {
                            metPurchLine = purchLine.metPurchLine();

                            //Extended table design pattern was introduced late. Some extension records may not exist
                            if(!metPurchLine)
                            {
                                metPurchLine = purchLine.metCreateMETPurchLine();
                            }

                            metPurchLine.updateIntegrationStatus(integrationStatus);

                            processingStatus = METProcessingStatus::Success;
                            processingMessage = "@MET:PurchaseOrderLineUpdateSuccessful";
                        }
                        else
                        {
                            processingStatus = METProcessingStatus::Error;
                            processingMessage = "@MET:PurchaseOrderLineNotFound";
                        }
                    }
                } //changeCompany
            }
        }
        catch (Exception::Deadlock)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    error("@MET:PickListUpdateFailedDatabaseDeadlockOccurred");
                    throw Exception::Deadlock;
                }
                else
                {
                    retry;
                }
            }
            else
            {
                error("@MET:PickListUpdateFailedDatabaseDeadlockOccurred");
                throw Exception::Deadlock;
            }
        }
        catch (Exception::UpdateConflict)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    error("@MET:PurchaseOrderUpdateFailedDatabaseConflict");
                    throw Exception::UpdateConflictNotRecovered;
                }
                else
                {                            
                    retry;
                }
            }
            else
            {
                error("@MET:PurchaseOrderUpdateFailedDatabaseConflict");
                throw Exception::UpdateConflict;
            }
        }
        
        return [processingStatus, processingMessage];
       
    }

Public static METPurchaseOrderLineService construct()
{
    return new METPurchaseOrderLineService();
}
